widget.solution:
import numpy as np

def rolling_beta(x, m, window):
    x, m = np.asarray(x, float), np.asarray(m, float)
    out = []
    for t in range(window, len(x) + 1):
        xs, ms = x[t - window:t], m[t - window:t]
        cov = np.sum((xs - xs.mean()) * (ms - ms.mean()))
        out.append(cov / np.sum((ms - ms.mean()) ** 2))
    return np.array(out)
